{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Acamprosate, a small polar ionizable molecule with an amide and sulfonate, has absolute oral bioavailability of only 11 ± 1% in humans; its high transfer score and shared polar/ionizable character support low bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ferulic acid, a phenolic carboxylic acid, shows only 3–10% oral bioavailability in humans, supporting low absorption for highly polar carboxylic-acid-containing structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Oseltamivir carboxylate, the free ionized carboxylic acid metabolite, has <5% oral bioavailability in humans when given directly; this directly supports low bioavailability for the query's ionized dicarboxylic acid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Tegaserod has an absolute oral bioavailability of approximately 10% in healthy volunteers, providing additional transferable evidence that compounds with substantial polarity and hydrogen-bonding capacity often fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tetrahydrouridine, a highly polar nucleoside with multiple hydrogen-bond donors and acceptors, has only 4.1% oral bioavailability in humans, reinforcing the low-F pattern for polar, poorly permeable molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low oral bioavailability: multiple transferable experimental analogues with polar, ionizable, hydrogen-bond-rich structures show absolute oral bioavailability of 4–11%, well below the 20% threshold. The query's extreme polarity, full ionization at physiological pH, high TPSA, and multiple H-bond donors further support low permeability and low F. High-F records for oseltamivir carboxylate reflect prodrug administration and are not applicable to the free diacid query.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule itself.",
    "No permeability, transporter, or metabolic stability data are available for the query.",
    "Transfer scores are moderate-to-high but not exact structural matches; cyclic peptide behavior could differ from linear polar acids.",
    "Possible active uptake or prodrug-like behavior was not experimentally assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

